package types

import (
	"encoding/hex"
	"fmt"
)

// MaxAttestationEvidenceSize caps MsgAttestIdentityLink.evidence_uri.
const MaxAttestationEvidenceSize = 512

// IdentityLinkProofPrefix opens every identity link proof string.
const IdentityLinkProofPrefix = "sparkdream-identity-link"

// IdentityLinkProofString is the text a member publishes from the remote
// identity (a post, profile field or record) to prove control of it for a
// link to a bridge peer:
//
//	sparkdream-identity-link:<chain_id>:<local_address>:<hex(challenge)>
//
// The challenge is the link's own, generated by MsgLinkIdentity from block
// data and the (local_address, peer_id, remote_identity) triple, so the
// string cannot be precomputed before the claim exists and a claim made
// again after an unlink needs a new proof. A bridge operator fetches the
// evidence, checks that remote_identity authored it and that it carries
// this string, then signs MsgAttestIdentityLink.
func IdentityLinkProofString(chainID, localAddress string, challenge []byte) string {
	return fmt.Sprintf("%s:%s:%s:%s", IdentityLinkProofPrefix, chainID, localAddress, hex.EncodeToString(challenge))
}
